    L.circleMarker([p.lat, p.lon], { radius: 6, color: '#fff', weight: 2, fillColor: color, fillOpacity: 1 }).bindTooltip(text, { permanent: true, direction: 'top', offset: [0, -6] }).addTo(boundaryLayer);
